#!/bin/bash
# Iterative FAC patch probes, experiments 1 and 2 at the production regime, h_b/S 1-2
# (dev hub, 2026-11-01: the ladder and the base at similar resolution). Problem A at 16
# and 24 rungs (h_b/S 1.21 and 1.82, np 1), the box at S h_b/2 (h_b/S 1.91, np 4; its
# tip and bridge follow the fixture's 3S rule). The patch is under 2000 rows here, so
# cut 1 is cut 0 and runs only with the slip coarse space. Same overlay as
# kaiju_commands.sh (probe/iterative-patch) and OMP_NUM_THREADS=1; the hypre arms run
# on kaiju only. Row 7 (../addon_matrix_2026_11/kaiju_commands_row7.sh) runs first.
set -u
cd "$(dirname "$0")"
mkdir -p records logs
export OMP_NUM_THREADS=1

# experiment 1: inexact block solves
python -u iterative_patch_linear.py -uw_n_rungs 16 -uw_block lu -uw_cut 0 -uw_out records/A_r16_cut0_lu.json > logs/A_r16_cut0_lu.log 2>&1
python -u iterative_patch_linear.py -uw_n_rungs 16 -uw_block fgmres -uw_block_pc ilu -uw_ilu_levels 1 -uw_rtol 1e-1 -uw_max_it 200 -uw_cut 0 -uw_out records/A_r16_cut0_fgmres_ilu1_rtol1e-1_it200.json > logs/A_r16_cut0_fgmres_ilu1_rtol1e-1_it200.log 2>&1
